    B.Text_0H8 = new A.Text("Khai kh\u1ea9n b\u1ed5 sung l\u01b0\u01a1ng th\u1ef1c m\u1ed9t l\u1ea7n; ph\xe1t tri\u1ec3n n\xf4ng nghi\u1ec7p t\u0103ng s\u1ea3n l\u01b0\u1ee3ng n\u1ec1n cho nh\u1eefng v\u1ee5 sau.", null, null, null, null, null, null, null, null, null);
    B.Text_167 = new A.Text("Ph\xe1i m\u1eadt th\xe1m", null, null, null, null, null, null, null, null, null);
    B.Text_1PN = new A.Text("Xem m\u1ee5c ti\xeau", null, null, null, null, null, null, null, null, null);
    B.Text_1SH = new A.Text("\u01afu ti\xean qu\xe2n \u0111\u1ed9i", null, null, null, null, null, null, null, null, null);
    B.Text_2QK = new A.Text("Ch\u01b0a c\xf3 qu\xe2n \u0111ang l\xe0m nhi\u1ec7m v\u1ee5.", null, null, null, null, null, null, null, null, null);
    B.Text_2mD = new A.Text("T\u1ed1n 1 h\xe0nh \u0111\u1ed9ng \xb7 \u0111\u1ebfn ngay \xb7 t\u1ed5ng qu\xe2n s\u1ed1 gi\u1eef nguy\xean.", null, null, null, null, null, null, null, null, null);
    B.Text_2yL = new A.Text("M\u1edf s\u1ed5 k\u1ebft qu\u1ea3 tri\u1ec1u \u0111\xecnh", null, null, null, null, null, null, null, null, null);
    B.Text_32a = new A.Text("S\u1ee9c m\u1ea1nh = qu\xe2n s\u1ed1 \xd7 s\u1eb5n s\xe0ng / 100 \xd7 h\u1ec7 s\u1ed1 ch\u1ec9 huy. Ch\u1ec9 s\u1ed1 kh\xf4ng gi\u1edbi h\u1ea1n \u1edf 100.", null, null, null, null, null, null, null, null, null);
    B.Text_3Ao = new A.Text("Kh\xf4ng c\xf2n t\u1ea5u ch\u1edd x\u1eed l\xfd.", null, B.TextStyle_aGE, null, null, null, null, null, null, null);
    B.Text_4DD = new A.Text("C\xf2n t\u1ea5u ch\u01b0\u01a1ng t\u1edbi h\u1ea1n", null, B.TextStyle_Min, null, null, null, null, null, null, null);
    B.Text_4Fq = new A.Text("B\u1eaft \u0111\u1ea7u tri\u1ec1u \u0111\u1ea1i m\u1edbi", null, null, null, null, null, null, null, null, null);
    B.ValueKey_FBv = new A.ValueKey("promotion-highest", type$.ValueKey_String);
    B.Text_4SD = new A.Text("\u0110\xe3 \u0111\u1ea1t Nh\u1ea5t ph\u1ea9m \u2014 ph\u1ea9m v\u1ecb cao nh\u1ea5t.", null, null, null, null, null, null, null, null, B.ValueKey_FBv);
    B.Text_4Ue = new A.Text("Xem th\u1eddi gian tr\u1ecb v\xec  \u2192", null, null, null, null, null, null, null, null, null);
    B.Text_51Y = new A.Text("B\u1ea3o d\u01b0\u1ee1ng v\xe0 tu b\u1ed5 ph\u1ee5c h\u1ed3i t\xecnh tr\u1ea1ng \u0111\xea. N\xe2ng c\u1ea5p t\u0103ng \u0111\u1ed9 b\u1ec1n c\xf4ng tr\xecnh, kh\xf4ng t\u1ef1 ph\u1ee5c h\u1ed3i \u0111\xea.", null, null, null, null, null, null, null, null, null);
    B.Text_5Fx = new A.Text("Ch\u01a1i l\u1ea1i", null, null, null, null, null, null, null, null, null);
    B.Text_5IN = new A.Text("Kh\xf4ng t\xecm th\u1ea5y trang n\xe0y.", null, null, null, null, null, null, null, null, null);
    B.TextStyle_vW9 = new A.TextStyle(true, B.Color_0ny, null, null, null, null, 10, null, null, null, null, null, 1.7, null, null, null, null, null, null, null, null, null, null, null, null, null);
    B.Text_5Z3 = new A.Text("Kho\u1ea3n thu/chi \u0111\u01b0\u1ee3c t\xednh trong d\u1ef1 to\xe1n v\xe0 s\u1ed5 thu chi. Thi\u1ebfu ti\u1ec1n s\u1ebd ghi n\u1ee3; h\u1ebft th\u1eddi h\u1ea1n ngh\u0129a v\u1ee5 kh\xf4ng x\xf3a kho\u1ea3n n\u1ee3 \u0111\xe3 ph\xe1t sinh.", null, B.TextStyle_vW9, null, null, null, null, null, null, null);
    B.Text_6EJ = new A.Text("B\u1ed9 l\u1ecdc", null, B.TextStyle_yFz, null, null, null, null, null, null, null);
    B.Text_6Kv = new A.Text("\u0110\xf3ng", null, null, null, null, null, null, null, null, null);
    B.TextStyle_UqC = new A.TextStyle(true, null, null, "Lora", null, null, 27, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null);
    B.Text_7PM = new A.Text("C\xe2u chuy\u1ec7n h\u1eadu cung", null, B.TextStyle_UqC, null, null, null, null, null, null, null);
    B.Text_7WN = new A.Text("Ch\u01b0a c\xf3 nhi\u1ec7m v\u1ee5 chi\u1ebfn tranh \u0111ang m\u1edf.", null, null, null, null, null, null, null, null, null);
    B.Text_7lO = new A.Text("Ti\u1ebfp t\u1ee5c c\xf9ng tuy\u1ebfn", null, null, null, null, null, null, null, null, null);
    B.Text_8IK = new A.Text("BI\xcaN NI\xcaN TRI\u1ec0U \u0110\u1ea0I", null, B.TextStyle_BpB, null, null, null, null, null, null, null);
    B.Text_8m1 = new A.Text("\u0110\xe3 ghi s\u1ed5\n\u0110\xe3 ph\xe1t sinh", null, B.TextStyle_wEY, B.TextAlign_1, null, null, null, null, null, null);
    B.Text_8mg = new A.Text("Ch\u01b0a ghi nh\u1eadn bi\u1ebfn \u0111\u1ed9ng.", null, null, null, null, null, null, null, null, null);
    B.Text_95a = new A.Text("B\u1ed5 nhi\u1ec7m", null, null, null, null, null, null, null, null, null);
    B.Text_9ce = new A.Text("\u0110i\u1ec1u qu\xe2n v\u1ec1 Kinh Th\xe0nh", null, null, null, null, null, null, null, null, null);
    B.Text_9vQ = new A.Text("G\u1eb7p nh\xe2n v\u1eadt", null, null, null, null, null, null, null, null, null);
    B.Text_A33 = new A.Text("Cho h\u1ed3i h\u01b0\u01a1ng", null, null, null, null, null, null, null, null, null);
    B.Text_AZR = new A.Text("Kh\xf4ng c\xf3 passive ch\u1ee9c v\u1ee5", null, B.TextStyle_Kpe, null, null, null, null, null, null, null);
    B.Text_B3y = new A.Text("M\u1ed7i t\xean l\u01b0u th\xe0nh t\xedch t\u1ed1t nh\u1ea5t. B\u1eb1ng th\u1eddi gian tr\u1ecb v\xec th\xec \u0111\u1ed3ng h\u1ea1ng. L\u01b0\u1ee3t b\u1ecf d\u1edf kh\xf4ng \u0111\u01b0\u1ee3c ghi \u0111i\u1ec3m.", null, B.TextStyle_Kpe, null, null, null, null, null, null, null);
    B.Text_BTW = new A.Text("\u0110\u1ebfn Ph\u1ee7 Tr\u1ea5n Th\u1ee7", null, null, null, null, null, null, null, null, null);
    B.Text_BVl = new A.Text("Tr\u1ea1ng th\xe1i passive", null, null, null, null, null, null, null, null, null);
    B.Text_C0L = new A.Text("Hi\u1ec7n t\u1ea1i:", null, null, null, null, null, null, null, null, null);
    B.Text_DKL = new A.Text("C\u1ea2NH B\xc1O: ph\u01b0\u01a1ng \xe1n n\xe0y l\xe0m \u1ed5n \u0111\u1ecbnh v\u1ec1 0 v\xe0 k\u1ebft th\xfac l\u01b0\u1ee3t ch\u01a1i.", null, B.TextStyle_Bsa, null, null, null, null, null, null, null);
    B.Text_DdB = new A.Text("Page Not Found", null, B.TextStyle_KXJ, null, null, null, null, null, null, null);
    B.Text_EIm = new A.Text("C\u1ea2NH B\xc1O: thay ng\u01b0\u1eddi l\xfac n\xe0y khi\u1ebfn \u1ed5n \u0111\u1ecbnh tri\u1ec1u \u0111\xecnh v\u1ec1 0 v\xe0 k\u1ebft th\xfac l\u01b0\u1ee3t ch\u01a1i.", null, B.TextStyle_Bsa, null, null, null, null, null, null, null);
    B.TextStyle_wL6 = new A.TextStyle(true, null, null, "Lora", null, null, 25, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null);
    B.Text_Ec2 = new A.Text("B\u1ea1n \u0111\xe3 tr\u1ecb v\xec \u0111\u01b0\u1ee3c", null, B.TextStyle_wL6, null, null, null, null, null, null, null);
    B.Text_Ecv = new A.Text("C\xf3 qu\xe2n b\xe1o xin ti\u1ebfp t\u1ebf \u0111ang ch\u1edd x\u1eed l\xfd.", null, B.TextStyle_Bsa, null, null, null, null, null, null, null);
    B.Text_EuW = new A.Text("H\xe0nh \u0111\u1ed9ng", null, B.TextStyle_Lt1, null, null, null, null, null, null, null);
    B.Text_Ev6 = new A.Text("Chi ph\xed", null, B.TextStyle_c5Z, null, null, null, null, null, null, null);
    B.Text_F6a = new A.Text("Ch\u01b0a c\xf3 quan ph\u1ee5 tr\xe1ch c\xf4ng vi\u1ec7c \u0111\u1ecba ph\u01b0\u01a1ng \u0111ang th\u1ef1c hi\u1ec7n.", null, null, null, null, null, null, null, null, null);
    B.Text_FZn = new A.Text("T\u1ea1m d\u1eebng, c\u1ea7n ng\u01b0\u1eddi thay.", null, B.TextStyle_Bsa, null, null, null, null, null, null, null);
    B.Text_Fc7 = new A.Text("\u0110\u1ebfn C\u1eeda \u1ea2i \u0111\u1ec3 ra l\u1ec7nh t\xe1c chi\u1ebfn", null, null, null, null, null, null, null, null, null);
    B.TextStyle_Gna = new A.TextStyle(true, B.Color_wst, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null);
    B.Text_FiA = new A.Text("Go to home page", null, B.TextStyle_Gna, null, null, null, null, null, null, null);
    B.Text_GAM = new A.Text("\xdd ch\u1ec9 c\u1ee7a b\u1ec7 h\u1ea1", null, B.TextStyle_Lt1, null, null, null, null, null, null, null);
    B.Text_HaA = new A.Text("B\u1ea3n l\u01b0u n\xe0y ch\u01b0a c\xf3 h\u1ec7 th\u1ed1ng bang giao v\xe0 qu\xe2n s\u1ef1 gi\u1eefa c\xe1c n\u01b0\u1edbc.", null, null, null, null, null, null, null, null, null);
    B.Text_Hdt = new A.Text("Ng\u01b0\u1eddi \u0111ang gi\u1eef ch\u1ee9c", null, null, null, null, null, null, null, null, null);
    B.Text_HfG = new A.Text("Xem t\u1ed5ng quan qu\xe2n \u0111\u1ed9i", null, null, null, null, null, null, null, null, null);
    B.Text_HmR = new A.Text("Xem scoreboard", null, null, null, null, null, null, null, null, null);
    B.Text_J2E = new A.Text("Qu\xe2n \u0111\u1ecbch \u0111ang giao chi\u1ebfn thu\u1ed9c c\xf9ng l\u1ef1c l\u01b0\u1ee3ng m\u1eb7t tr\u1eadn; t\u1ed5n th\u1ea5t \u0111\u01b0\u1ee3c tr\u1eeb khi qu\xe2n b\xe1o v\u1ec1.", null, B.TextStyle_nWK, null, null, null, null, null, null, null);
    B.Text_J4j = new A.Text("N\u0103ng l\u1ef1c cao kh\xf4ng b\u1ea3o \u0111\u1ea3m trung th\xe0nh hay li\xeam ch\xednh. C\xe1c ph\u1ea9m ch\u1ea5t ch\u01b0a \u0111i\u1ec1u tra v\u1eabn ch\u01b0a \u0111\u01b0\u1ee3c x\xe1c minh.", null, B.TextStyle_c9n, null, null, null, null, null, null, null);
    B.Text_J6z = new A.Text("S\u1eafp t\u1edbi\nD\u1ef1 ki\u1ebfn", null, B.TextStyle_FPC, B.TextAlign_1, null, null, null, null, null, null);
    B.Text_JDn = new A.Text("M\u1eadt th\xe1m c\xf3 th\u1ec3 t\u1eed n\u1ea1n v\u0129nh vi\u1ec5n. Th\u1ea5t b\u1ea1i m\u1ea5t kinh ph\xed, gi\u1eef h\u1ed3 s\u01a1 c\u0169. Ch\u1ec9 b\xe1o c\xe1o th\xe0nh c\xf4ng m\u1edbi t\u1ea1o b\u1eb1ng ch\u1ee9ng hi\u1ec7u l\u1ef1c m\u1ed9t n\u0103m.", null, B.TextStyle_qAh, null, null, null, null, null, null, null);
    B.Text_JSF = new A.Text("B\u1ed5 nhi\u1ec7m / h\u1ed3i h\u01b0\u01a1ng", null, null, null, null, null, null, null, null, null);
    B.Text_JYI = new A.Text("C\u1ea7n thi\u1ec7n c\u1ea3m \u226560 \u0111\u1ec3 m\u1edf c\xe2u chuy\u1ec7n c\xe1 nh\xe2n.", null, null, null, null, null, null, null, null, null);
    B.Text_KAg = new A.Text("Nh\u1eadn ng\u1ecdc t\u1ef7", null, null, null, null, null, null, null, null, null);
    B.Text_KCQ = new A.Text("B\u1eaft \u0111\u1ea7u tr\u1ecb v\xec   \u2192", null, null, null, null, null, null, null, null, null);
    B.Text_Kor = new A.Text("1 t\u1ea1 = 100 c\xe2n quy \u0111\u1ed5i. M\u1ed7i kho\u1ea3n thu/chi l\xe0m tr\xf2n l\xean m\u1ed9t l\u1ea7n \u0111\u1ebfn t\u1ea1 nguy\xean.", null, null, null, null, null, null, null, null, null);
    B.Text_Kwx = new A.Text("B\u1ed5 nhi\u1ec7m / \u0111i\u1ec1u chuy\u1ec3n", null, null, null, null, null, null, null, null, null);
    B.Text_LFQ = new A.Text("Nh\xe2n v\u1eadt kh\xf4ng c\xf2n hi\u1ec7n di\u1ec7n, ch\u01b0a th\u1ec3 th\u0103ng ph\u1ea9m.", null, null, null, null, null, null, null, null, null);
    B.Text_LGn = new A.Text("Ch\u1ecdn ng\u01b0\u1eddi x\u1eed l\xfd t\u1ea5u ch\u01b0\u01a1ng", null, null, null, null, null, null, null, null, null);
    B.Text_LHU = new A.Text("\u01afu ti\xean s\u1ea3n xu\u1ea5t", null, B.TextStyle_vPz, null, null, null, null, null, null, null);
    B.Text_MB6 = new A.Text("Ch\u01b0a x\u1eed l\xfd qu\u1ed1c s\u1ef1", null, B.TextStyle_liN, null, null, null, null, null, null, null);
    B.Text_Mv3 = new A.Text("Ch\u1ee9c v\u1ee5", null, null, null, null, null, null, null, null, null);
    B.Text_Nvl = new A.Text("\u0110\u1ecdc sau", null, null, null, null, null, null, null, null, null);
    B.Text_O3b = new A.Text("Th\xf4ng tin t\u1eeb tr\u1ea1ng th\xe1i hi\u1ec7n t\u1ea1i. Ban l\u1ec7nh t\u1ea1i Qu\u1ed1c s\u1ef1; \u0111\u1ed5i \u01b0u ti\xean s\u1ea3n xu\u1ea5t t\u1ea1i Ng\xe2n kh\u1ed1.", null, B.TextStyle_nWK, null, null, null, null, null, null, null);
    B.Text_OCd = new A.Text("C\xf4ng th\xe0nh b\u1eaft bu\u1ed9c \xedt nh\u1ea5t 200% qu\xe2n \u0111\u1ecbch.", null, null, null, null, null, null, null, null, null);
    B.Text_ODV = new A.Text("X\xe1c nh\u1eadn \u0111i\u1ec1u qu\xe2n", null, null, null, null, null, null, null, null, null);
    B.Text_Oss = new A.Text("Ban l\u1ec7nh", null, null, null, null, null, null, null, null, null);
    B.Text_PE6 = new A.Text("X\xe1c nh\u1eadn ng\u1ef1 ph\xea", null, null, null, null, null, null, null, null, null);
    B.TextStyle_ply = new A.TextStyle(true, null, null, "Lora", null, null, 14, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null);
    B.ValueKey_mPW = new A.ValueKey("annual-tax-plan", type$.ValueKey_String);
    B.Text_PTO = new A.Text("Thu\u1ebf v\u1ee5 Thu \u2014 k\u1ebf ho\u1ea1ch thu n\u0103m", null, B.TextStyle_ply, null, null, null, null, null, null, B.ValueKey_mPW);
    B.TextStyle_TeE = new A.TextStyle(true, B.Color_Q2K, null, null, null, null, 11, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null);
    B.Text_Qcu = new A.Text("L\xe0m th\xeam", null, B.TextStyle_TeE, null, null, null, null, null, null, null);
    B.Text_Qks = new A.Text("X\xe1c nh\u1eadn th\u0103ng ph\u1ea9m", null, null, null, null, null, null, null, null, null);
    B.Text_QoQ = new A.Text("Hi\u1ec3n th\u1ecb 150 ghi ch\xe9p g\u1ea7n nh\u1ea5t; l\u1ecbch s\u1eed \u0111\u1ea7y \u0111\u1ee7 v\u1eabn n\u1eb1m trong b\u1ea3n l\u01b0u.", null, B.TextStyle_Kpe, null, null, null, null, null, null, null);
    B.Text_QpK = new A.Text("Giao thi\u1ec7p v\u1edbi v\u01b0\u01a1ng tri\u1ec1u n\u01b0\u1edbc b\u1ea1n. M\u1ed7i quy\u1ebft \u0111\u1ecbnh c\xf3 chi ph\xed v\xe0 \u1ea3nh h\u01b0\u1edfng \u0111\u1ebfn quan h\u1ec7 hai n\u01b0\u1edbc.", null, null, null, null, null, null, null, null, null);
    B.Text_RUd = new A.Text("Th\u1eadn tr\u1ecdng: s\u1ee9c ti\u1ebfn c\xf4ng \xd70,95, th\u01b0\u01a1ng vong c\u01a1 s\u1edf \xd70,8. Ch\u1ee7 \u0111\u1ed9ng: s\u1ee9c ti\u1ebfn c\xf4ng \xd71,10, th\u01b0\u01a1ng vong c\u01a1 s\u1edf \xd71,2.", null, null, null, null, null, null, null, null, null);
    B.Text_RhK = new A.Text("V\u1ec1 Qu\u1ed1c s\u1ef1", null, null, null, null, null, null, null, null, null);
    B.Text_S6a = new A.Text("C\u1ea2NH B\xc1O: cho h\u1ed3i h\u01b0\u01a1ng l\xfac n\xe0y l\xe0m \u1ed5n \u0111\u1ecbnh v\u1ec1 0 v\xe0 k\u1ebft th\xfac l\u01b0\u1ee3t ch\u01a1i.", null, B.TextStyle_Bsa, null, null, null, null, null, null, null);
    B.Text_S84 = new A.Text("Ch\u01b0a c\xf3 ng\u01b0\u1eddi nh\u1eadp cung.", null, null, null, null, null, null, null, null, null);
    B.Text_S9B = new A.Text("B\u1eaft \u0111\u1ea7u l\u1ea1i s\u1ebd thay l\u01b0\u1ee3t \u0111ang ch\u01a1i. L\u01b0\u1ee3t b\u1ecb b\u1ecf kh\xf4ng \u0111\u01b0\u1ee3c ghi th\xe0nh t\xedch.", null, B.TextStyle_qAh, null, null, null, null, null, null, null);
    B.Text_SJy = new A.Text("\u01afu ti\xean c\u1ee9u t\u1ebf", null, null, null, null, null, null, null, null, null);
    B.Text_SOA = new A.Text("Nhi\u1ec7m v\u1ee5 d\xe0i c\xf3 y\xeau c\u1ea7u ti\u1ebfp t\u1ebf gi\u1eefa ch\u1eebng. Theo d\xf5i Qu\xe2n s\u1ef1 tr\u01b0\u1edbc khi kh\xe9p m\xf9a.", null, null, null, null, null, null, null, null, null);
    B.Text_SQF = new A.Text("Ch\u01b0a c\xf3 chi\u1ebfn d\u1ecbch \u0111ang m\u1edf v\u1edbi n\u01b0\u1edbc n\xe0y.", null, null, null, null, null, null, null, null, null);
    B.Text_SRE = new A.Text("V\u1ec1 trang ch\xednh", null, null, null, null, null, null, null, null, null);
    B.Text_SyV = new A.Text("V\u1ec1 trang gi\u1edbi thi\u1ec7u", null, null, null, null, null, null, null, null, null);
    B.Text_T4F = new A.Text("Tri\u1ec7u ki\u1ebfn", null, B.TextStyle_bmX, null, null, null, null, null, null, null);
    B.Text_T9X = new A.Text("Ch\u1ecdn s\u1ed1 qu\xe2n v\xe0 t\u01b0\u1edbng \u0111\u1ec3 d\u1ef1 t\xednh c\u01a1 h\u1ed9i th\u1eafng.", null, null, null, null, null, null, null, null, null);
    B.Text_Td3 = new A.Text("Home", null, null, null, null, null, null, null, null, null);
    B.Text_U7d = new A.Text("M\u01b0\u1eddi t\xe1m tu\u1ed5i, b\u1ea1n nh\u1eadn ng\u1ecdc t\u1ef7. T\u1eeb h\xf4m nay, v\u1eadn m\u1ec7nh giang s\u01a1n n\u1eb1m trong t\u1eebng quy\u1ebft \u0111\u1ecbnh.", null, null, null, null, null, null, null, null, null);
    B.Text_VC7 = new A.Text("Tuy\u1ec3n qu\xe2n t\u1ea1i Qu\u1ed1c s\u1ef1; t\xe2n binh t\u1eadp k\u1ebft \u1edf Kinh Th\xe0nh.", null, B.TextStyle_nWK, null, null, null, null, null, null, null);
    B.Text_Vbn = new A.Text("L\u01b0u \xfd", null, B.TextStyle_c5Z, null, null, null, null, null, null, null);
    B.Text_VgJ = new A.Text("Ch\u01b0a c\xf3 c\xf4ng vi\u1ec7c \u0111ang th\u1ef1c hi\u1ec7n.", null, null, null, null, null, null, null, null, null);
    B.Text_WBc = new A.Text("Ch\u01b0a c\xf3 t\u1ea5u b\xe1o li\xean quan \u0111ang ch\u1edd x\u1eed l\xfd.", null, null, null, null, null, null, null, null, null);
    B.Text_WX2 = new A.Text("M\u1edf s\u1ed5 \u2192", null, B.TextStyle_YaE0, B.TextAlign_1, null, null, null, null, null, null);
    B.Text_Waq = new A.Text("Ng\u01b0\u1eddi h\u1ed3i h\u01b0\u01a1ng \u0111\u01b0\u1ee3c l\u01b0u trong danh s\xe1ch ch\u1edd v\u1edbi tr\u1ea1ng th\xe1i \u0110\xe3 h\u1ed3i h\u01b0\u01a1ng, gi\u1eef nguy\xean ph\u1ea9m, c\xf4ng tr\u1ea1ng v\xe0 quan h\u1ec7.", null, null, null, null, null, null, null, null, null);
    B.Text_XgW = new A.Text("L\u1ecbch s\u1eed c\xf4ng tr\u1ea1ng", null, null, null, null, null, null, null, null, null);
    B.Text_Xm0 = new A.Text("Bi\xean gi\u1edbi \u0111ang h\xf2a b\xecnh. Theo d\xf5i t\xecnh h\xecnh ho\u1eb7c x\u1eed l\xfd ngo\u1ea1i giao t\u1ea1i Ph\u1ee7 Tr\u1ea5n Th\u1ee7.", null, null, null, null, null, null, null, null, null);
    B.Text_YM9 = new A.Text("Ti\u1ebfp t\u1ee5c tr\u1ecb v\xec", null, null, null, null, null, null, null, null, null);
    B.Text_Ydt = new A.Text("C\xe2n nh\u1eafc l\u1ea1i", null, null, null, null, null, null, null, null, null);
    B.Text_ZE2 = new A.Text("\u0110\u1ea1o qu\xe2n \u0111ang c\u1ea7n ti\u1ebfp t\u1ebf.", null, B.TextStyle_Bsa, null, null, null, null, null, null, null);
    B.Text_ajV = new A.Text("\u0110\u1ec3 l\xfac kh\xe1c", null, null, null, null, null, null, null, null, null);
    B.Text_akA = new A.Text("Ch\u1ecdn m\u1ed9t ph\u1ea9m \u0111\u1ee7 \u0111i\u1ec1u ki\u1ec7n \u0111\u1ec3 xem tr\u01b0\u1edbc v\xe0 x\xe1c nh\u1eadn.", null, B.TextStyle_aGE, null, null, null, null, null, null, null);
    B.Text_b0k = new A.Text("Th\u01b0\u01a1ng l\u01b0\u1ee3ng h\xf2a b\xecnh, theo d\xf5i h\xf2a \u01b0\u1edbc v\xe0 c\xe1c k\u1ef3 tri\u1ec1u c\u1ed1ng gi\u1eefa hai n\u01b0\u1edbc.", null, null, null, null, null, null, null, null, null);
    B.Text_bL6 = new A.Text("\u0110\u1ec3 sau", null, null, null, null, null, null, null, null, null);
    B.Text_bSo = new A.Text("Ch\u01a1i theo m\xf9a \xb7 12 h\xe0nh \u0111\u1ed9ng m\u1ed7i m\xf9a \xb7 T\u1ef1 l\u01b0u", null, B.TextStyle_Zot, null, null, null, null, null, null, null);
    B.Text_bl5 = new A.Text("Ch\u01b0a c\xf3 c\xf4ng vi\u1ec7c d\xe0i h\u1ea1n. H\xe3y ch\u1ecdn ng\u01b0\u1eddi v\xe0 giao vi\u1ec7c.", null, B.TextStyle_aGE, null, null, null, null, null, null, null);
    B.Text_bpc = new A.Text("B\u1ecf qua", null, null, null, null, null, null, null, null, null);
    B.Text_cPW = new A.Text("Ch\u1ecdn qu\xe2n v\xe0 t\u01b0\u1edbng", null, null, null, null, null, null, null, null, null);
    B.Text_d7b = new A.Text("Chi\u1ebfn d\u1ecbch li\xean quan", null, B.TextStyle_Ryn, null, null, null, null, null, null, null);
    B.Text_dEb = new A.Text("\u0110\u1ebfn Qu\u1ed1c s\u1ef1", null, null, null, null, null, null, null, null, null);
    B.Text_dJD = new A.Text("B\u1ed9 m\xe1y tri\u1ec1u \u0111\xecnh", null, null, null, null, null, null, null, null, null);
    B.Text_ddS = new A.Text("Ch\u1ee9c v\u1ee5 \u0111ang tr\u1ed1ng", null, null, null, null, null, null, null, null, null);
    B.Text_ddo = new A.Text("\u01afu ti\xean khi thi\u1ebfu ti\u1ec1n", null, B.TextStyle_vPz, null, null, null, null, null, null, null);
    B.Text_df3 = new A.Text("T\u1ed5n th\u1ea5t t\xednh tr\xean qu\xe2n tham chi\u1ebfn, theo ch\u1ec9 huy v\xe0 ch\xeanh l\u1ec7ch qu\xe2n s\u1ed1. Khi th\u1eafng gi\u1ea3m 50\u201375% th\u01b0\u01a1ng vong c\u01a1 s\u1edf; t\u01b0\u1edbng thi\u1ec7n c\u1ea3m th\u1ea5p c\xf3 th\u1ec3 t\u1ef1 \xfd r\xfat qu\xe2n.", null, null, null, null, null, null, null, null, null);
    B.Text_dhb = new A.Text("\u0110\u1ed5i ch\u1ed7 hai quan", null, null, null, null, null, null, null, null, null);
    B.Text_eUW = new A.Text("\u0110\u1ed1i chi\u1ebfu kh\u1ea9u ph\u1ea7n \u2014 kh\xf4ng ph\u1ea3i nh\u1eadp kho", null, B.TextStyle_ply, null, null, null, null, null, null, null);
    B.Text_eik = new A.Text("\u01afu ti\xean s\u1ea3n xu\u1ea5t m\xf9a t\u1edbi", null, null, null, null, null, null, null, null, null);
    B.Text_fTy = new A.Text("\u0110\u01b0\u1eddng ti\u1ebfp t\u1ebf g\u1eb7p kh\xf3 kh\u0103n. C\u1ea7n ti\u1ebfp t\u1ebf ho\u1eb7c r\xfat qu\xe2n; b\u1ecf m\u1eb7c khi\u1ebfn nhi\u1ec7m v\u1ee5 th\u1ea5t b\u1ea1i.", null, B.TextStyle_Bsa, null, null, null, null, null, null, null);
    B.Text_flD = new A.Text("C\xe2u chuy\u1ec7n & passive", null, null, null, null, null, null, null, null, null);
    B.Text_fnB = new A.Text("Quay l\u1ea1i x\u1eed l\xfd", null, null, null, null, null, null, null, null, null);
    B.Text_gMc = new A.Text("Chi 1.000 ng\xe2n l\u01b0\u1ee3ng v\xe0 1 h\xe0nh \u0111\u1ed9ng. Ng\u01b0\u1eddi \u0111\u01b0\u1ee3c b\u1ed5 nhi\u1ec7m +5 thi\u1ec7n c\u1ea3m.", null, null, null, null, null, null, null, null, null);
    B.Text_ho3 = new A.Text("Khi thi\u1ebfu ti\u1ec1n, kho\u1ea3n \u01b0u ti\xean \u0111\u01b0\u1ee3c thanh to\xe1n tr\u01b0\u1edbc. Thay ch\xednh s\xe1ch t\u1ed1n 1 h\xe0nh \u0111\u1ed9ng.", null, null, null, null, null, null, null, null, null);
    B.Text_ibB = new A.Text("B\u1ecf tr\u1ed1ng", null, B.TextStyle_Bsa, null, null, null, null, null, null, null);
    B.Text_ii0 = new A.Text("L\u1ef1c l\u01b0\u1ee3ng \u1edf nh\xe0 xu\u1ed1ng th\u1ea5p, c\xf3 th\u1ec3 kh\xf4ng \u0111\u1ee7 x\u1eed l\xfd t\u1eadp k\xedch ho\u1eb7c c\u1ee9u vi\u1ec7n.", null, B.TextStyle_Bsa, null, null, null, null, null, null, null);
    B.TextStyle_MMW = new A.TextStyle(true, B.Color_xZs, null, null, null, null, 11, B.FontWeight_5, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null);
    B.Text_ilW = new A.Text("Nguy\xean nh\xe2n k\u1ebft th\xfac", null, B.TextStyle_MMW, null, null, null, null, null, null, null);
    B.Text_jUC = new A.Text("1.000 ng\xe2n l\u01b0\u1ee3ng \xb7 1 h\xe0nh \u0111\u1ed9ng \xb7 Ng\u01b0\u1eddi c\u0169 \u221210, ng\u01b0\u1eddi m\u1edbi +5 thi\u1ec7n c\u1ea3m", null, B.TextStyle_Kpe, null, null, null, null, null, null, null);
    B.Text_jg0 = new A.Text("V\u1ec1 m\xe0n h\xecnh ch\xednh", null, null, null, null, null, null, null, null, null);
    B.Text_jrT = new A.Text("Th\u1ef1c hi\u1ec7n", null, null, null, null, null, null, null, null, null);
    B.Text_kNG = new A.Text("X\xe1c nh\u1eadn", null, null, null, null, null, null, null, null, null);
    B.Text_ku9 = new A.Text("Th\u1eed \u0111\u1ecdc l\u1ea1i b\u1ea3n l\u01b0u", null, null, null, null, null, null, null, null, null);
    B.Text_kxb = new A.Text("Ch\u01b0a c\xf3 chi\u1ebfn d\u1ecbch \u0111ang th\u1ef1c hi\u1ec7n.", null, null, null, null, null, null, null, null, null);
    B.Text_lgA = new A.Text("Xem k\u1ebft qu\u1ea3", null, null, null, null, null, null, null, null, null);
    B.Text_m1H = new A.Text("Kh\xf4ng c\xf3 ng\u01b0\u1eddi gi\u1eef ch\u1ee9c M\u1eadt th\xe1m.", null, B.TextStyle_Bsa, null, null, null, null, null, null, null);
    B.Text_m20 = new A.Text("Thay \u0111\u1ed5i ng\u01b0\u1eddi qu\u1ea3n l\xfd", null, null, null, null, null, null, null, null, null);
    B.Text_mEy = new A.Text("\u0110i\u1ec1u qu\xe2n", null, null, null, null, null, null, null, null, null);
    B.Text_mXV = new A.Text("B\u1ea5m t\xean \u0111\u1ec3 xem h\u1ed3 s\u01a1 quan. Tuy\u1ec3n d\u1ee5ng, b\u1ed5 nhi\u1ec7m v\xe0 b\xe3i nhi\u1ec7m t\u1ea1i Ph\u1ee7 B\xe1 Quan.", null, B.TextStyle_Kpe, null, null, null, null, null, null, null);
    B.Text_n60 = new A.Text("X\xe1c nh\u1eadn giao vi\u1ec7c", null, null, null, null, null, null, null, null, null);
    B.TextStyle_iLl = new A.TextStyle(true, B.Color_xZs, null, null, null, null, 10, null, null, 1.4, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null);
    B.Text_nDz = new A.Text("B\u1ec6 H\u1ea0 \u0110ANG C\xc2N NH\u1eaeC", null, B.TextStyle_iLl, null, null, null, null, null, null, null);
    B.Text_ndN = new A.Text("S\u1eb5n s\xe0ng = 30% hu\u1ea5n luy\u1ec7n + 25% qu\xe2n kh\xed + 20% s\u0129 kh\xed + 25% h\u1eadu c\u1ea7n.", null, null, null, null, null, null, null, null, null);
    B.Text_nmr = new A.Text("\u0110\u1ebfn Ph\u1ee7 B\xe1 Quan", null, null, null, null, null, null, null, null, null);
    B.Text_oQY = new A.Text("C\xf3 th\u1ec3 \u0111\u1ec3 l\xfac kh\xe1c; tuy\u1ebfn v\xe0 ti\u1ebfn \u0111\u1ed9 \u0111\u01b0\u1ee3c gi\u1eef nguy\xean.", null, B.TextStyle_Kpe, null, null, null, null, null, null, null);
    B.Text_oQk = new A.Text("H\xf2a \u0111\xe0m: m\u1ed7i s\u1ee9 \u0111o\xe0n t\u1ed1n 1 h\xe0nh \u0111\u1ed9ng. Y\xeau c\u1ea7u \u0111\u1ed1i ph\u01b0\u01a1ng c\u1ed1ng: ph\xed 1.000 l\u01b0\u1ee3ng v\xe0ng; c\u1ea7u h\xf2a: ph\xed 2.000 l\u01b0\u1ee3ng v\xe0ng.", null, null, null, null, null, null, null, null, null);
    B.Text_oV6 = new A.Text("H\u1ee7y", null, null, null, null, null, null, null, null, null);
    B.Text_oov = new A.Text("Giao ng\u01b0\u1eddi kh\xf4ng t\u1ed1n th\xeam h\xe0nh \u0111\u1ed9ng. Ng\u01b0\u1eddi \u0111\u01b0\u1ee3c giao s\u1ebd b\u1eadn \u0111\u1ebfn khi c\xf3 k\u1ebft qu\u1ea3. \u0110\u1ec3 m\u1eb7c \u0111\u1ecbnh s\u1ebd kh\xf4ng t\u1ef1 ch\u1ecdn ng\u01b0\u1eddi thay b\u1ea1n.", null, B.TextStyle_3KY, null, null, null, null, null, null, null);
    B.Text_pX3 = new A.Text("X\xe1c nh\u1eadn xu\u1ea5t qu\xe2n", null, null, null, null, null, null, null, null, null);
    B.Text_peE = new A.Text("Ch\u1ecdn ch\xednh s\xe1ch \u0111\u1ec3 ban h\xe0nh. Thay ch\xednh s\xe1ch t\u1ed1n 1 h\xe0nh \u0111\u1ed9ng. Kho\u1ea3n \u0111\u01b0\u1ee3c \u01b0u ti\xean s\u1ebd thanh to\xe1n tr\u01b0\u1edbc khi ng\xe2n kh\u1ed1 kh\xf4ng \u0111\u1ee7 tr\u1ea3 t\u1ea5t c\u1ea3.", null, B.TextStyle_Kpe, null, null, null, null, null, null, null);
    B.Text_q10 = new A.Text("Qu\xe2n tri\u1ec1u \u0111\xecnh \u0111\xf3ng t\u1ea1i c\u1eeda \u1ea3i \u0111\u1ed1i di\u1ec7n. \u0110\u1ebfn \u0111\xf3 \u0111\u1ec3 \u0111i\u1ec1u qu\xe2n, ch\u1ecdn t\u01b0\u1edbng, xu\u1ea5t tr\u1eadn ho\u1eb7c ti\u1ebfp t\u1ebf.", null, null, null, null, null, null, null, null, null);
    B.Text_rAI = new A.Text("B\u1ea3ng x\u1ebfp h\u1ea1ng", null, B.TextStyle_bmX, null, null, null, null, null, null, null);
    B.Text_rrU = new A.Text("Ti\u1ebfp nh\u1eadn t\u1ea5u b\xe1o, giao vi\u1ec7c v\xe0 theo d\xf5i thi h\xe0nh t\u1ea1i \u0111\u1ecba ph\u01b0\u01a1ng.", null, B.TextStyle_nWK, null, null, null, null, null, null, null);
    B.Text_sJ6 = new A.Text("Tri\u1ec1u th\u1ea7n", null, B.TextStyle_m0H, null, null, null, null, null, null, null);
    B.Text_syg = new A.Text("Nh\u1ea5n n\xfat m\u0169i t\xean tr\xean th\u1ebb \u0111\u1ec3 th\u1ef1c hi\u1ec7n. Ch\u1ec9 xem tr\u01b0\u1edbc ch\u01b0a ti\xeau h\xe0nh \u0111\u1ed9ng.", null, B.TextStyle_Kpe, null, null, null, null, null, null, null);
    B.Text_uCK = new A.Text("Page Not Found", null, null, null, null, null, null, null, null, null);
    B.Text_uHR = new A.Text("Ba n\u01b0\u1edbc l\xe2n c\u1eadn; ch\u1ec9 m\u1ed9t cu\u1ed9c chi\u1ebfn c\xf9ng l\xfac. Th\u1eafng \u0111\u1ec3 k\xfd h\xf2a \u01b0\u1edbc tri\u1ec1u c\u1ed1ng, kh\xf4ng s\xe1p nh\u1eadp l\xe3nh th\u1ed5.", null, null, null, null, null, null, null, null, null);
    B.Text_uON = new A.Text("Chong \u0111\xe8n l\xe0m th\xeam?", null, B.TextStyle_Min, null, null, null, null, null, null, null);
    B.Text_ubL = new A.Text("B\u1ea3n l\u01b0u c\u0169 v\u01b0\u1ee3t 10 ng\u01b0\u1eddi: kh\xf3a tuy\u1ec3n th\xeam; ch\u1ec9 10 ng\u01b0\u1eddi \u0111\xf3ng g\xf3p, lu\xf4n g\u1ed3m Ho\xe0ng h\u1eadu.", null, B.TextStyle_Bsa, null, null, null, null, null, null, null);
    B.TextStyle_JK5 = new A.TextStyle(true, B.Color_ISm, null, "Lora", null, null, 14, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null);
    B.Text_ups = new A.Text("T\xe1c \u0111\u1ed9ng khi ng\u1ef1 ph\xea", null, B.TextStyle_JK5, null, null, null, null, null, null, null);
    B.Text_uzY = new A.Text("S\u1eed quan \u0111ang ch\u1edd ghi ch\xe9p \u0111\u1ea7u ti\xean.", null, B.TextStyle_HH1, null, null, null, null, null, null, null);
    B.Text_vo0 = new A.Text("Ph\u1ea9m y\xeau c\u1ea7u", null, null, null, null, null, null, null, null, null);
    B.Text_wWH = new A.Text("Ch\u01b0a c\xf3 \u0111\u1ee3t \u0111ang th\u1ef1c hi\u1ec7n.", null, null, null, null, null, null, null, null, null);
    B.Text_xZP = new A.Text("\u0110\u1ebfn S\u1ee9 qu\xe1n", null, null, null, null, null, null, null, null, null);
    B.Text_yAv = new A.Text("Ch\u1ecdn m\u1eadt th\xe1m v\xe0 t\u1ed5ng kinh ph\xed. Chi 1 h\xe0nh \u0111\u1ed9ng, nh\u1eadn b\xe1o c\xe1o sau 2 m\xf9a. M\u1eadt th\xe1m b\u1eadn trong th\u1eddi gian \u0111i\u1ec1u tra.", null, null, null, null, null, null, null, null, null);
    B.Text_zXv = new A.Text("01", null, B.TextStyle_FPC, null, null, null, null, null, null, null);
    B.Text_zYQ = new A.Text("M\u1ed9t tri\u1ec1u \u0111\u1ea1i m\u1edbi", null, B.TextStyle_Min, null, null, null, null, null, null, null);
